{"command": "cd /private/var/folders/kp/vdv61pd97vd0x29b257r8h7h0000gn/T/barcode-k2y90xh1 && python3 << 'EOF'
from PIL import Image
import colorsys

im = Image.open('barcode.png').convert('RGB')
W,H = im.size
px = im.load()
cols=[]
for x in range(W):
    r=g=b=0
    for y in range(H):
        pr,pg,pb=px[x,y]
        r+=pr; g+=pg; b+=pb
    cols.append((r/H,g/H,b/H))

def lum(c): return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]

# strongly colored columns
print("Columns with saturation > 0.35 and val > 0.25 (colorful moments):")
runs=[]
cur=None
for x in range(W):
    c=cols[x]
    h,s,v=colorsys.rgb_to_hsv(c[0]/255,c[1]/255,c[2]/255)
    if s>0.35 and v>0.25:
        if cur is None: cur=[x,x,h]
        else: cur[1]=x; cur[2]=(cur[2]+h)/2
    else:
        if cur is not None and cur[1]-cur[0]>=2: runs.append(tuple(cur))
        cur=None
if cur and cur[1]-cur[0]>=2: runs.append(tuple(cur))
for a,b,h in runs:
    hh=h*360
    name=('red' if hh<20 or hh>=340 else 'orange' if hh<45 else 'yellow' if hh<70 else 'green' if hh<160 else 'cyan' if hh<200 else 'blue' if hh<260 else 'purple' if hh<300 else 'pink')
    print(f"  x={a}-{b} ({a/10:.1f}%-{b/10:.1f}%) hue~{hh:.0f} {name}")

# very dark runs and very bright runs
print("\nDark runs (lum<40):")
cur=None
for x in range(W):
    l=lum(cols[x])
    if l<40:
        if cur is None: cur=[x,x]
        else: cur[1]=x
    else:
        if cur and cur[1]-cur[0]>=3: print(f"  {cur[0]}-{cur[1]} ({cur[0]/10:.0f}%-{cur[1]/10:.0f}%)")
        cur=None
if cur and cur[1]-cur[0]>=3: print(f"  {cur[0]}-{cur[1]}")

print("\nBright runs (lum>150):")
cur=None
for x in range(W):
    l=lum(cols[x])
    if l>150:
        if cur is None: cur=[x,x]
        else: cur[1]=x
    else:
        if cur and cur[1]-cur[0]>=3: print(f"  {cur[0]}-{cur[1]} ({cur[0]/10:.0f}%-{cur[1]/10:.0f}%)")
        cur=None
if cur and cur[1]-cur[0]>=3: print(f"  {cur[0]}-{cur[1]}")

# print every 20px compact color swatch description
print("\nEvery-2% average colors:")
for i in range(50):
    seg=cols[i*20:(i+1)*20]
    n=len(seg)
    r=sum(c[0] for c in seg)/n; g=sum(c[1] for c in seg)/n; b=sum(c[2] for c in seg)/n
    l=lum((r,g,b))
    h,s,v=colorsys.rgb_to_hsv(r/255,g/255,b/255)
    print(f"  {i*2:3d}%: ({r:3.0f},{g:3.0f},{b:3.0f}) lum={l:3.0f} hue={h*360:5.1f} sat={s:.2f}")
EOF"}

